477	function parseThresholds(thresholdStrings: string[] | undefined): Record<string, number> | null {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return null;
480	  }
481	
482	  const result: Record<string, number> = {};
483	  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];
484	
485	  for (const thresholdStr of thresholdStrings) {
486	    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
487	    if (!match) {
488	      log.error(`Malformed threshold: "${thresholdStr}". Expected format: <metric>=<number>`);
489	      process.exit(2);
490	    }
491	
492	    const [, metricId, minStr] = match;
493	    const min = Number.parseFloat(minStr);
494	
495	    if (!validMetricIds.includes(metricId)) {
496	      log.error(`Unknown metric ID: "${metricId}". Valid options: ${validMetricIds.join(', ')}`);
497	      process.exit(2);
498	    }
499	
500	    if (Number.isNaN(min) || min < 0 || min > 1) {
501	      log.error(`Invalid threshold minimum: "${minStr}". Must be a number between 0 and 1`);
502	      process.exit(2);
503	    }
504	
505	    result[metricId] = min;
506	  }
507	
508	  return result;
509	}
